eventlist)A ,LATERAL FLATTEN (INPUT => A.VALUE:FeeList) B group by 1,2,3,4,5)) where rw = 1 and lower(fee_type) like any (\'%disposal%\',\'%removal%\') group by 1,2,3,4) ; CREATE OR REPLACE TABLE VAHDAM_DB.MAPLEMONK.VAHDAM_UK_MONTHLY_STORAGE_FEES_PR AS WITH STORAGECOST AS (WITH DATES AS ( with RECURSIVE date_range AS ( SELECT TO_DATE(\'2023-04-01\') AS date_value UNION ALL SELECT date_value + INTERVAL \'1 day\' FROM date_range WHERE date_value + INTERVAL \'1 day\' <= \'2025-03-31\' ) SELECT date_value FROM date_range), STORAGE AS (select date,replace(fee_type,\'\"\"\',\'\') Fee_type,replace(CURRENCY,\'\"\"\',\'\') CURRENCY, sum(amount) Amount from ( select *, dense_rank() over (partition by order_id,date order by date) rw from (select date,servicefeeeventlist,A.value:AmazonOrderId Order_id,B.value:FeeType Fee_type,B.value:\"FeeAmount\":\"CurrencyCode\" CURRENCY, sum(B.value:\"FeeAmount\":\"CurrencyAmount\") Amount from (select date, servicefeeeventlist from (select servicefeeeventlist,_airbyte_emitted_at::date Date, row_number() over (partition by servicefeeeventlist order by _airbyte_emitted_at::date asc) rw from vahdam_db.maplemonk.CASP_UK_NEW_listfinancialevents) where rw = 1 and lower(servicefeeeventlist) like \'%storage%\' ) ,LATERAL FLATTEN (INPUT => servicefeeeventlist)A ,LATERAL FLATTEN (INPUT => A.VALUE:FeeList) B group by 1,2,3,4,5)) where rw = 1 and lower(fee_type) like \'%storage%\' AND CURRENCY = \'GBP\' group by 1,2,3) SELECT COALESCE(D.DATE_VALUE,S.DATE) AS DATE, IFNULL(S.FEE_TYPE,\'NA\') FEE_TYPE, IFNULL(S.CURRENCY,\'NA\') CURRENCY,SUM(IFNULL(S.AMOUNT,0)) AMOUNT FROM DATES D LEFT JOIN STORAGE S ON D.DATE_VALUE=S.DATE GROUP BY 1,2,3) SELECT MONTH,YEAR,SUM(IFNULL(STFS_CURRENT_MONTH,0)) STFS_CURRENT_MONTH, SUM(IFNULL(LTFS_CURRENT_MONTH,0)) LTFS_CURRENT_MONTH FROM (SELECT MONTH(DATE) AS MONTH, YEAR(DATE) AS YEAR,CASE WHEN FEE_TYPE = \'FBAStorageFee\' THEN SUM(IFNULL(AMOUNT,0)) ELSE 0 END AS STFS_CURRENT_MONTH ,CASE WHEN FEE_TYPE = \'FBALongTermStorageFee\' THEN SUM(IFNULL(AMOUNT,0)) ELSE 0 END AS LTFS_CURRENT_MONTH FROM STORAGECOST GROUP BY FEE_TYPE,1,2 ORDER BY 2,1) GROUP BY 1,2 ORDER BY 2,1; CREATE OR REPLACE TABLE VAHDAM_DB.MAPLEMONK.VAHDAM_ROE_MONTHLY_STORAGE_FEES_PR AS WITH STORAGECOST AS (WITH DATES AS ( with RECURSIVE date_range AS ( SELECT TO_DATE(\'2023-04-01\') AS date_value UNION ALL SELECT date_value + INTERVAL \'1 day\' FROM date_range WHERE date_value + INTERVAL \'1 day\' <= \'2026-03-31\' ) SELECT date_value FROM date_range), STORAGE AS (select date,replace(fee_type,\'\"\"\',\'\') Fee_type,replace(CURRENCY,\'\"\"\',\'\') CURRENCY, sum(amount) Amount from ( select *, dense_rank() over (partition by order_id,date order by date) rw from (select date,servicefeeeventlist,A.value:AmazonOrderId Order_id,B.value:FeeType Fee_type,B.value:\"FeeAmount\":\"CurrencyCode\" CURRENCY, sum(B.value:\"FeeAmount\":\"CurrencyAmount\") Amount from (select date, servicefeeeventlist from (select servicefeeeventlist,_airbyte_emitted_at::date Date, row_number() over (partition by servicefeeeventlist order by _airbyte_emitted_at::date asc) rw from vahdam_db.maplemonk.CASP_UK_NEW_listfinancialevents) where rw = 1 and lower(servicefeeeventlist) like \'%storage%\' ) ,LATERAL FLATTEN (INPUT => servicefeeeventlist)A ,LATERAL FLATTEN (INPUT => A.VALUE:FeeList) B group by 1,2,3,4,5)) where rw = 1 and lower(fee_type) like \'%storage%\' AND CURRENCY = \'EUR\' group by 1,2,3) SELECT COALESCE(D.DATE_VALUE,S.DATE) AS DATE, IFNULL(S.FEE_TYPE,\'NA\') FEE_TYPE, IFNULL(S.CURRENCY,\'NA\') CURRENCY,SUM(IFNULL(S.AMOUNT,0)) AMOUNT FROM DATES D LEFT JOIN STORAGE S ON D.DATE_VALUE=S.DATE GROUP BY 1,2,3) SELECT MONTH,YEAR,SUM(IFNULL(STFS_CURRENT_MONTH,0)) STFS_CURRENT_MONTH, SUM(IFNULL(LTFS_CURRENT_MONTH,0)) LTFS_CURRENT_MONTH FROM (SELECT MONTH(DATE) AS MONTH, YEAR(DATE) AS YEAR,CASE WHEN FEE_TYPE = \'FBAStorageFee\' THEN SUM(IFNULL(AMOUNT,0)) ELSE 0 END AS STFS_CURRENT_MONTH ,CASE WHEN FEE_TYPE = \'FBALongTermStorageFee\' THEN SUM(IFNULL(AMOUNT,0)) ELSE 0 END AS LTFS_CURRENT_MONTH FROM STORAGECOST GROUP BY FEE_TYPE,1,2 ORDER BY 2,1) GROUP BY 1,2 ORDER BY 2,1; Create or replace table vahdam_db.maplemonk.VAHDAM_ASP_UK_REFUND_SHIPMENT_ORDER_ID as With Refund as (Select AMAZONORDERID ,SELLERSKU ,min(POSTEDDATE::date) as POSTEDDATE ,sum(ifnull(Tax,0)) Refund_Tax ,sum(ifnull(Principal,0)) Refund_Principal ,sum(ifnull(Refund_Promotion,0)) Refund_Promotion ,sum(ifnull(ShippingTax,0)) Refund_ShippingTax ,sum(ifnull(ShippingCharge,0)) Refund_ShippingCharge ,sum(ifnull(GiftWrap,0)) Refund_GiftWrap ,sum(ifnull(GiftWrapTax,0)) Refund_GiftWrapTax ,sum(ifnull(ExportCharge,0)) Refund_ExportCharge ,sum(ifnull(ReturnShipping,0)) Refund_ReturnShipping ,sum(ifnull(GenericDeduction,0)) Refund_GenericDeduction ,sum(ifnull(Goodwill,0)) Refund_Goodwill ,sum(ifnull(Commission,0)) Refund_Commission ,sum(ifnull(RefundCommission,0)) Refund_RefundCommission ,sum(ifnull(GiftwrapChargeback,0)) Refund_GiftwrapChargeback ,sum(ifnull(ShippingChargeback,0)) Refund_ShippingChargeback ,sum(ifnull(Quantity,0)) Refund_Quantity ,sum(ifnull(Refund_MarketplaceFacilitatorTax_Other,0)) as Refund_MarketplaceFacilitatorTax_Other ,sum(ifnull(Refund_MarketplaceFacilitatorVat_Shipping,0)) as Refund_MarketplaceFacilitatorVat_Shipping ,sum(ifnull(Refund_MarketplaceFacilitatorVat_Principal,0)) as Refund_MarketplaceFacilitatorVat_Principal from vahdam_db.maplemonk.vahdam_UK_refund_event_list group by 1,2), Orders as ( select * from (select SKU , ASIN , row_number() over (partition by SKU order by ASIN) rw from ( select distinct SKU, ASIN from vahdam_db.maplemonk.ASP_UK_GET_FLAT_FILE_ALL_ORDERS_DATA_BY_LAST_UPDATE_GENERAL where year(\"purchase-date\"::date) >= \'2023\' and lower(\"sales-channel\") = \'amazon.co.uk\' and sku is not null ) ) where rw=1 ), Shipment as (select AMAZONORDERID ,SELLERSKU ,MarketplaceName ,min(POSTEDDATE::date) as POSTEDDATE ,sum(QUANTITY) QUANTITY ,sum(PRINCIPAL) PRINCIPAL ,sum(FBAPERUNITFULFILLMENTFEE) FBAPERUNITFULFILLMENTFEE ,sum(COMMISSION) COMMISSION ,sum(PROMOTION) PROMOTION ,sum(TAX) TAX ,sum(GIFTWRAP) GIFTWRAP ,sum(GIFTWRAPTAX) GIFTWRAPTAX ,sum(SHIPPINGCHARGE) SHIPPINGCHARGE ,sum(SHIPPINGTAX) SHIPPINGTAX ,sum(MARKETPLACEFACILITATORTAXOTHER) MARKETPLACEFACILITATORTAXOTHER ,sum(MARKETPLACEFACILITATORVATSHIPPING) MARKETPLACEFACILITATORVATSHIPPING ,sum(MARKETPLACEFACILITATORVATPRINCIPAL) MARKETPLACEFACILITATORVATPRINCIPAL ,sum(FIXEDCLOSINGFEE) FIXEDCLOSINGFEE ,sum(GIFTWRAPCHARGEBACK) GIFTWRAPCHARGEBACK ,sum(SHIPPINGCHARGEBACK) SHIPPINGCHARGEBACK ,sum(VARIABLECLOSINGFEE) VARIABLECLOSINGFEE from vahdam_db.maplemonk.vahdam_UK_shipment_event_list group by 1,2,3) select coalesce(S.POSTEDDATE,R.POSTEDDATE)::date POSTEDDATE ,coalesce(S.AMAZONORDERID,R.AMAZONORDERID) AMAZONORDERID ,coalesce(S.SELLERSKU,R.SELLERSKU) SELLERSKU ,O.ASIN as ASIN ,S.MarketplaceName MarketplaceName ,S.QUANTITY ,S.PRINCIPAL ,S.FBAPERUNITFULFILLMENTFEE ,S.COMMISSION ,S.PROMOTION ,S.TAX ,ifnull(R.Refund_Tax,0) Refund_Tax ,ifnull(R.Refund_Principal,0) Refund_Principal ,ifnull(R.Refund_Promotion,0) Refund_Promotion ,ifnull(R.Refund_ShippingTax,0) Refund_ShippingTax ,ifnull(R.Refund_ShippingCharge,0) Refund_ShippingCharge ,ifnull(R.Refund_GiftWrap,0) Refund_GiftWrap ,ifnull(R.Refund_GiftWrapTax,0) Refund_GiftWrapTax ,ifnull(R.Refund_ExportCharge,0) Refund_ExportCharge ,ifnull(R.Refund_ReturnShipping,0) Refund_ReturnShipping ,ifnull(R.Refund_GenericDeduction,0) Refund_GenericDeduction ,ifnull(R.Refund_Goodwill,0) Refund_Goodwill ,ifnull(R.Refund_Commission,0) Refund_Commission ,ifnull(R.Refund_RefundCommission,0) Refund_RefundCommission ,ifnull(R.Refund_GiftwrapChargeback,0) Refund_GiftwrapChargeback ,ifnull(R.Refund_ShippingChargeback,0) Refund_ShippingChargeback ,ifnull(R.Refund_Quantity,0) Refund_Quantity ,ifnull(R.Refund_MarketplaceFacilitatorTax_Other,0) as Refund_MarketplaceFacilitatorTax_Other ,ifnull(R.Refund_MarketplaceFacilitatorVat_Shipping,0) as Refund_MarketplaceFacilitatorVat_Shipping ,ifnull(R.Refund_MarketplaceFacilitatorVat_Principal,0)as Refund_MarketplaceFacilitatorVat_Principal ,S.GIFTWRAP ,S.GIFTWRAPTAX ,S.SHIPPINGCHARGE ,S.SHIPPINGTAX ,S.MARKETPLACEFACILITATORTAXOTHER ,S.MARKETPLACEFACILITATORVATSHIPPING ,S.MarketplaceFacilitatorVATPrincipal ,S.FIXEDCLOSINGFEE ,S.GIFTWRAPCHARGEBACK ,S.SHIPPINGCHARGEBACK ,S.VARIABLECLOSINGFEE from Shipment S full outer join Refund R on S.AMAZONORDERID = R.AMAZONORDERID and lower(S.SELLERSKU) = lower(R.SELLERSKU) left join Orders O on lower(S.SELLERSKU) = lower(O.SKU) where lower(MarketplaceName) = \'amazon.co.uk\' order by POSTEDDATE desc; Create or replace table vahdam_db.maplemonk.ASP_UK_ASIN_Payment_Reports_Budget_Tracking as with Payments as ( select POSTEDDATE::date as Date ,SELLERSKU ,ASIN ,MarketplaceName ,sum(ifnull(PRINCIPAL,0))+sum(ifnull(PROMOTION,0))+sum(ifnull(TAX,0))+sum(ifnull(REFUND_TAX,0))+sum(ifnull(REFUND_PRINCIPAL,0))+sum(ifnull(REFUND_PROMOTION,0))+sum(ifnull(REFUND_SHIPPINGTAX,0))+sum(ifnull(REFUND_SHIPPINGCHARGE,0))+sum(ifnull(REFUND_GIFTWRAP,0))+sum(ifnull(REFUND_GIFTWRAPTAX,0))+sum(ifnull(REFUND_EXPORTCHARGE,0))+sum(ifnull(REFUND_RETURNSHIPPING,0))+sum(ifnull(REFUND_GENERICDEDUCTION,0))+sum(ifnull(REFUND_GOODWILL,0))+sum(ifnull(REFUND_GIFTWRAPCHARGEBACK,0))+sum(ifnull(REFUND_SHIPPINGCHARGEBACK,0))+sum(ifnull(REFUND_MARKETPLACEFACILITATORTAX_OTHER,0))+sum(ifnull(REFUND_MARKETPLACEFACILITATORVAT_SHIPPING,0))+sum(ifnull(REFUND_MARKETPLACEFACILITATORVAT_PRINCIPAL,0))+sum(ifnull(GIFTWRAP,0))+sum(ifnull(GIFTWRAPTAX,0))+sum(ifnull(SHIPPINGCHARGE,0))+sum(ifnull(SHIPPINGTAX,0))+sum(ifnull(MARKETPLACEFACILITATORTAXOTHER,0))+sum(ifnull(MARKETPLACEFACILITATORVATSHIPPING,0))+sum(ifnull(MARKETPLACEFACILITATORVATPRINCIPAL,0))+sum(ifnull(FIXEDCLOSINGFEE,0))+sum(ifnull(GIFTWRAPCHARGEBACK,0))+sum(ifnull(SHIPPINGCHARGEBACK,0))+sum(ifnull(VARIABLECLOSINGFEE,0)) as Sales ,-1*sum(ifnull(FBAPERUNITFULFILLMENTFEE,0)) as FBA_Fees ,-1*(sum(ifnull(Commission,0))+sum(ifnull(REFUND_COMMISSION,0))+sum(ifnull(REFUND_REFUNDCOMMISSION,0))) as Commission ,sum(ifnull(quantity,0)) as Quantity_sold ,sum(ifnull(refund_quantity,0)) Refund_Quanity ,sum(ifnull(quantity,0))-sum(ifnull(refund_quantity,0)) as Units from vahdam_db.maplemonk.VAHDAM_ASP_UK_REFUND_SHIPMENT_ORDER_ID group by 1,2,3,4 ), ADJUSTMENT AS (select posteddate::DATE AS DATE ,COALESCE(A.sellersku,O.SKU) SKU ,O.ASIN ,sum(ifnull(COMPENSATED_CLAWBACK_QUANTITY,0)) + sum(ifnull(WAREHOUSE_DAMAGE_QUANTITY,0)) + sum(ifnull(REVERSAL_REIMBURSEMENT_QUANTITY,0)) + sum(ifnull(WAREHOUSE_LOST_MANUAL_QUANTITY,0)) + sum(ifnull(WAREHOUSE_DAMAGE_EXCEPTION_QUANTITY,0)) as TOTAL_ADJUSTMENT_QTY ,sum(ifnull(COMPENSATED_CLAWBACK_TOTAL_AMOUNT,0)) COMPENSATED_CLAWBACK_TOTAL_AMOUNT ,sum(ifnull(WAREHOUSE_DAMAGE_TOTAL_AMOUNT,0)) WAREHOUSE_DAMAGE_TOTAL_AMOUNT ,sum(ifnull(REVERSAL_REIMBURSEMENT_TOTAL_AMOUNT,0)) REVERSAL_REIMBURSEMENT_TOTAL_AMOUNT ,sum(ifnull(WAREHOUSE_LOST_MANUAL_TOTAL_AMOUNT,0)) WAREHOUSE_LOST_MANUAL_TOTAL_AMOUNT ,sum(ifnull(WAREHOUSE_DAMAGE_EXCEPTION_TOTAL_AMOUNT,0)) WAREHOUSE_DAMAGE_EXCEPTION_TOTAL_AMOUNT ,sum(ifnull(COMPENSATED_CLAWBACK_TOTAL_AMOUNT,0))+sum(ifnull(WAREHOUSE_DAMAGE_TOTAL_AMOUNT,0))+sum(ifnull(REVERSAL_REIMBURSEMENT_TOTAL_AMOUNT,0))+sum(ifnull(WAREHOUSE_LOST_MANUAL_TOTAL_AMOUNT,0))+sum(ifnull(WAREHOUSE_DAMAGE_EXCEPTION_TOTAL_AMOUNT,0)) as OTHER_SALES from vahdam_db.maplemonk.vahdam_uk_adjustment_event_list A LEFT JOIN ( select * from (select SKU , case when sku = \'Uncommingled.MSKU.1614859309584\' then \'B08Y1FH4ZP\' else ASIN end as ASIN , row_number() over (partition by SKU order by ASIN) rw from ( select distinct SKU, ASIN from Vahdam_db.maplemonk.ASP_UK_GET_FLAT_FILE_ALL_ORDERS_DATA_BY_LAST_UPDATE_GENERAL where year(\"purchase-date\"::date) >= \'2023\' and sku is not null ) ) where rw=1 ) O ON LOWER(A.SELLERSKU) = LOWER(O.SKU) where A.currency = \'GBP\' group by 1,2,3), Budget as ( Select Budget_month ,ASIN ,sum(Per_unit_Cogs) as Per_unit_Cogs ,sum(Per_unit_Outbound) as Per_unit_Outbound ,sum(Budget_units) as Budget_units ,sum(ASP) as Budget_ASP ,sum(Budget_revenue) as Budget_revenue ,sum(Budget_COGS) as Budget_COGS ,sum(Budget_Commission) as Budget_Commission ,sum(Budget_Outbound) as Budget_Outbound ,sum(Budget_Storage) as Budget_Storage ,sum(Budget_Last_mile) as Budget_FBA ,sum(Budget_PM_Spend) as Budget_PM_Spend ,sum(Budget_revenue)-sum(Budget_COGS)-sum(Budget_Commission)-sum(Budget_Outbound)-sum(Budget_Storage)-sum(Budget_Last_mile)-sum(Budget_PM_Spend) as Budget_CM2 ,sum(Budget_revenue)-sum(Budget_COGS)-sum(Budget_Commission)-sum(Budget_Outbound)-sum(Budget_Storage)-sum(Budget_Last_mile) as Budget_CM1 ,sum(ifnull(Budget_Revenue_INR,0)) Budget_Revenue_INR ,sum(ifnull(Budget_COGS_INR,0)) Budget_COGS_INR ,sum(ifnull(Budget_Commission_INR,0)) Budget_Commission_INR ,sum(ifnull(Budget_Outbound_INR,0)) Budget_Outbound_INR ,sum(ifnull(Budget_Storage_INR,0)) Budget_Storage_INR ,sum(ifnull(Budget_FBA_INR,0)) Budget_FBA_INR ,sum(ifnull(Budget_CM1_INR,0)) Budget_CM1_INR ,sum(ifnull(Budget_PM_SPEND_INR,0)) Budget_PM_SPEND_INR ,sum(ifnull(Budget_CM2_INR,0)) Budget_CM2_INR ,row_number() over (partition by Budget_month,asin order by sum(Budget_units) desc) rw from ( select try_to_date(month) as Budget_Month ,asin as ASIN ,cast(\"Per Units COGS\" as float) as Per_Unit_COGS ,cast(\"Per Unit Outbound\" as float) as Per_unit_outbound ,cast(units as float) as Budget_units ,cast(ASP as float) as ASP ,cast(Revenue as float) as Budget_revenue ,cast(COGS as float) as Budget_COGS ,cast(\"Comm \" as float) as Budget_Commission ,cast(\"Outbound \" as float) as Budget_Outbound ,cast(Storage as float) as Budget_Storage ,cast(\"Last Mile \" as float) as Budget_Last_mile ,cast(\"PM SPEND\" as float) as Budget_PM_Spend ,cast(\"Revenue(INR)\" as float) as Budget_Revenue_INR ,cast(\"REVISED COGS\" as float) as Budget_COGS_INR ,cast(\"Comm (INR)\" as float) as Budget_Commission_INR ,cast(\"Outbound(INR)\" as float) as Budget_Outbound_INR ,cast(\"Storage(INR)\" as float) as Budget_Storage_INR ,cast(\"Last Mile (INR)\" as float) as Budget_FBA_INR ,cast(\"CM1 (INR)\" as float) as Budget_CM1_INR ,cast(\"PM SPEND (INR)\" as float) as Budget_PM_SPEND_INR ,cast(\"CM2\" as float) as Budget_CM2_INR ,row_number() over (partition by month,asin order by cast(units as float) desc) rw from vahdam_db.maplemonk.gs_fy24_budget_consol_backup where lower(channel) = \'amazon\' and lower(platform) = \'uk\' UNION ALL SELECT TO_DATE(month, \'MON-YY\') AS Date, ASIN, div0( try_cast(replace(replace(COGS, \',\', \'\'), \'-\', \'\') as float), try_cast(replace(replace(UNITS, \',\', \'\'), \'-\', \'\') as float) ) AS Per_Unit_COGS, div0( try_cast(replace(replace(OUTBOUND, \',\', \'\'), \'-\', \'\') as float), try_cast(replace(replace(UNITS, \',\', \'\'), \'-\', \'\') as float) ) AS Per_Unit_Outbound, try_cast(replace(replace(UNITS, \',\', \'\'), \'-\', \'\') as float) AS Budget_Units, try_cast(replace(replace(ASP, \',\', \'\'), \'-\', \'\') as float) AS ASP, try_cast(replace(replace(REVENUE, \',\', \'\'), \'-\', \'\') as float) AS Budget_Revenue, try_cast(replace(replace(COGS, \',\', \'\'), \'-\', \'\') as float) AS Budget_COGS, try_cast(replace(replace(COMM, \',\', \'\'), \'-\', \'\') as float) AS Budget_Commission, try_cast(replace(replace(OUTBOUND, \',\', \'\'), \'-\', \'\') as float) AS Budget_Outbound, try_cast(replace(replace(STORAGE, \',\', \'\'), \'-\', \'\') as float) AS Budget_Storage, try_cast(replace(replace(\"Last Mile\", \',\', \'\'), \'-\', \'\') as float) AS Budget_Last_Mile, try_cast(replace(replace(\"PM SPEND\", \',\', \'\'), \'-\', \'\') as float) AS Budget_PM_Spend, try_cast(replace(replace(\"Revenue(INR)\", \',\', \'\'), \'-\', \'\') as float) AS Budget_Revenue_INR, try_cast(replace(replace(\"REVISED COGS\", \',\', \'\'), \'-\', \'\') as float) AS Budget_COGS_INR, try_cast(replace(replace(\"Comm (INR)\", \',\', \'\'), \'-\', \'\') as float) AS Budget_Commission_INR, try_cast(replace(replace(\"Outbound(INR)\", \',\', \'\'), \'-\', \'\') as float) AS Budget_Outbound_INR, try_cast(replace(replace(\"