hdam_db.maplemonk.sku_mapping_raw_data) where rw = 1 or rw is null ), STORAGE AS (SELECT case when COALESCE(A.MONTH,B.MONTH) = 1 then 13 else COALESCE(A.MONTH,B.MONTH) end Month ,case when COALESCE(A.MONTH,B.MONTH) = 1 then COALESCE(A.YEAR,B.YEAR)-1 else COALESCE(A.YEAR,B.YEAR) end Year ,SUM(IFNULL(A.STFS_CURRENT_MONTH,0)) STFS_CURRENT_MONTH ,SUM(IFNULL(A.LTFS_CURRENT_MONTH,0)) LTFS_CURRENT_MONTH ,SUM(IFNULL(B.STFS_CURRENT_MONTH,0)) STFS_LAST_MONTH ,SUM(IFNULL(B.LTFS_CURRENT_MONTH,0)) LTFS_LAST_MONTH FROM VAHDAM_DB.MAPLEMONK.VAHDAM_UK_MONTHLY_STORAGE_FEES_PR A LEFT JOIN VAHDAM_DB.MAPLEMONK.VAHDAM_UK_MONTHLY_STORAGE_FEES_PR B ON A.MONTH-1 = B.MONTH AND A.YEAR = B.YEAR GROUP BY 1,2 ORDER BY 2,1), COB_LIB as (select * from ( select asin, \"OB PER UNIT (CAL)\" as OB_PU, \"COGS PER UNIT (CAL)\" as COGS_PU, row_number() over (partition by asin order by \"COGS PER UNIT (CAL)\" desc) as rw from vahdam_db.maplemonk.VAHDAM_COGSOB_LIB_SHEET1 where lower(GEO) = \'uk\' ) t where rw = 1) select coalesce(P.date,ADJ.DATE,A.date,AD.date_value,B.Budget_month,R.DATE) as Date ,coalesce(P.ASIN,ADJ.ASIN,A.asin,AD.ASIN,B.ASIN,M.\"Amazon UK\",CL.ASIN) as ASIN ,CASE WHEN IFNULL(P.Sales, 0) = 0 AND IFNULL(B.Budget_Revenue, 0) = 0 AND IFNULL(A.Total_amazon_spend, 0) = 0 AND IFNULL(ADJ.OTHER_SALES, 0) = 0 THEN \'No Activity\' ELSE \'Active\' END AS Row_Status ,ifnull(ADJ.OTHER_SALES,0) as OTHER_SALES ,ifnull(P.Sales,0) as Sales ,ifnull(P.Quantity_sold,0) Quantity_sold ,ifnull(P.Refund_Quanity,0) Refund_Quanity ,ifnull(P.Units,0) as Units ,IFNULL(ADJ.TOTAL_ADJUSTMENT_QTY,0) AS TOTAL_ADJUSTMENT_QTY ,ifnull(P.Commission,0) as Commission ,ifnull(P.FBA_Fees,0) as FBA_Fees ,ifnull(A.Total_amazon_spend,0) as Total_Marketing_Spend ,CL.\"COGS_PU\" Per_unit_Cogs ,CL.\"OB_PU\" Per_unit_Outbound ,(case when month(coalesce(P.date,A.date,AD.date_value,B.Budget_month)) in (\'4\',\'5\') then 0 when month(coalesce(P.date,A.date,AD.date_value,B.Budget_month)) in (\'6\') then 0 else 0 end) *B.Per_unit_Outbound as Add_Per_unit_Outbound ,R.FBA_DISPOSAL_FEE*div0(ifnull(P.Sales,0),sum(ifnull(P.sales,0)) over (partition by coalesce(P.date,ADJ.DATE,A.date,AD.date_value,B.Budget_month,R.DATE) order by coalesce(P.date,ADJ.DATE,A.date,AD.date_value,B.Budget_month,R.DATE))) FBA_DISPOSAL_FEE ,R.FBA_REMOVAL_FEE*div0(ifnull(P.Sales,0),sum(ifnull(P.sales,0)) over (partition by coalesce(P.date,ADJ.DATE,A.date,AD.date_value,B.Budget_month,R.DATE) order by coalesce(P.date,ADJ.DATE,A.date,AD.date_value,B.Budget_month,R.DATE))) FBA_REMOVAL_FEE ,B.Budget_ASP ,B.Budget_units/dayofmonth(last_day(coalesce(p.date,b.budget_month))) as Daily_Budget_Units ,B.Budget_Revenue/dayofmonth(last_day(coalesce(p.date,b.budget_month))) as Daily_Budget_Revenue ,B.Budget_COGS/dayofmonth(last_day(coalesce(p.date,b.budget_month))) as Daily_Budget_COGS ,B.Budget_Commission/dayofmonth(last_day(coalesce(p.date,b.budget_month))) as Daily_Budget_Commission ,B.Budget_Outbound/dayofmonth(last_day(coalesce(p.date,b.budget_month))) as Daily_Budget_Outbound ,B.Budget_Storage/dayofmonth(last_day(coalesce(p.date,b.budget_month))) as Daily_Budget_Storage ,B.Budget_FBA/dayofmonth(last_day(coalesce(p.date,b.budget_month))) as Daily_Budget_FBA ,B.Budget_PM_Spend/dayofmonth(last_day(coalesce(p.date,b.budget_month))) as Daily_Budget_PM_Spend ,B.Budget_CM2/dayofmonth(last_day(coalesce(p.date,b.budget_month))) as Daily_Budget_CM2 ,B.Budget_CM1/dayofmonth(last_day(coalesce(p.date,b.budget_month))) as Daily_Budget_CM1 ,B.Budget_Revenue_INR/dayofmonth(last_day(coalesce(p.date,b.budget_month))) as Daily_Budget_Revenue_INR ,B.Budget_COGS_INR/dayofmonth(last_day(coalesce(p.date,b.budget_month))) as Daily_Budget_COGS_INR ,B.Budget_Commission_INR/dayofmonth(last_day(coalesce(p.date,b.budget_month))) as Daily_Budget_Commission_INR ,B.Budget_Outbound_INR/dayofmonth(last_day(coalesce(p.date,b.budget_month))) as Daily_Budget_Outbound_INR ,B.Budget_Storage_INR/dayofmonth(last_day(coalesce(p.date,b.budget_month))) as Daily_Budget_Storage_INR ,B.B